//! Deferred owner-bound Telegram questions. All transport evidence is fictional/loopback.
async fn telegram_question_binding(c:&mut PgConnection)->(TelegramSettings,TelegramIdentity){
 sqlx::raw_sql("DROP TABLE IF EXISTS rust_telegram_outbox,rust_telegram_runtime,agent_telegram_deliveries,agent_telegram_state;CREATE TABLE agent_telegram_state(key text PRIMARY KEY,next_update_id bigint NOT NULL DEFAULT 0,bot_id text,last_poll_at timestamptz,last_error text,evidence_type text NOT NULL DEFAULT 'unverified');CREATE TABLE agent_telegram_deliveries(update_id bigint PRIMARY KEY,reply text NOT NULL,state text NOT NULL CHECK(state IN('pending','sending','sent')))").execute(&mut *c).await.unwrap();sqlx::raw_sql(include_str!("../../sql/003_telegram.sql")).execute(&mut *c).await.unwrap();let settings=TelegramSettings::from_values(&telegram_values("http://127.0.0.1:54321"),true).unwrap().unwrap();let identity=TelegramIdentity{id:123,username:"fictional_bot".into()};telegram::initialize(c,&settings,&identity).await.unwrap();(settings,identity)
}
async fn telegram_question_fixture()->(PgConnection,Value,Value,Value,TelegramSettings,TelegramIdentity){
 let(mut c,packet,intent)=owner_question_packet().await;let(settings,identity)=telegram_question_binding(&mut c).await;let mut q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();q["state"]=json!("sent");q["message_ids"]=json!([33]);q["delivery_binding"]=json!(settings.binding());browser_save(&mut c,&format!("exec_q:{}",q["id"].as_str().unwrap()),q.clone()).await;(c,packet,intent,q,settings,identity)
}
async fn telegram_answer_update(c:&mut PgConnection,settings:&TelegramSettings,identity:&TelegramIdentity,update:Value)->Result<bool>{let config=Configuration::from_values(&queue_runtime_values()).unwrap();telegram::receive_configured(c,settings,identity,&update,&Wake::default(),Some(&config)).await}
fn telegram_answer(id:i64,text:&str)->Value{let mut update=telegram_update(id,text);update["message"]["reply_to_message"]=json!({"message_id":33});update}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_question_reply_uses_same_guarded_field_update_and_retains_exact_owner_update_provenance(){
 let(mut c,packet,intent,q,settings,identity)=telegram_question_fixture().await;let update=telegram_answer(70,"Day");assert!(telegram_answer_update(&mut c,&settings,&identity,update.clone()).await.unwrap());let answered=browser_pref(&mut c,&format!("exec_q:{}",q["id"].as_str().unwrap())).await;assert_eq!(answered["state"],"answered");assert_eq!(answered["provenance"]["source"],"owner_telegram");assert_eq!(answered["provenance"]["owner_user_id"],11);assert_eq!(answered["provenance"]["update_id"],70);assert_eq!(answered["provenance"]["reply_message_id"],33);assert_eq!(answered["reuse_approved"],false);let field:Value=sqlx::query_scalar("SELECT to_jsonb(f) FROM application_packet_fields f WHERE id=$1").bind(packet["fields"][7]["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert_eq!(field["answer_revision"],packet["fields"][7]["answer_revision"].as_i64().unwrap()+1);assert_eq!(field["provenance"]["telegram_owner_update"],70);assert_eq!(field["review_status"],"pending");assert_eq!(browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await["state"],"PREPARING");let before=browser_snapshot(&mut c).await;assert!(!telegram_answer_update(&mut c,&settings,&identity,update).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM rust_telegram_outbox WHERE update_id=70").fetch_one(&mut c).await.unwrap(),1);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_question_reply_denies_wrong_owner_forward_expiry_and_unbound_legacy_prompt_without_saving_answer(){
 let(mut c,packet,_intent,q,settings,identity)=telegram_question_fixture().await;let key=format!("exec_q:{}",q["id"].as_str().unwrap());for index in 0..4{let mut question=q.clone();let mut update=telegram_answer(80+index,"Day");match index{0=>update["message"]["from"]["id"]=json!(999),1=>update["message"]["forward_origin"]=json!({"type":"user"}),2=>question["expires_at"]=json!("2000-01-01T00:00:00Z"),_=>{question.as_object_mut().unwrap().remove("delivery_binding");}}browser_save(&mut c,&key,question.clone()).await;let allowed=telegram_answer_update(&mut c,&settings,&identity,update).await.unwrap();assert_eq!(allowed,index>=2);assert_eq!(browser_pref(&mut c,&key).await,question);let saved:Option<String>=sqlx::query_scalar("SELECT human_answer FROM application_packet_fields WHERE id=$1").bind(packet["fields"][7]["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert!(saved.is_none());}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_question_rejected_choice_rolls_back_savepoint_but_acknowledges_update_once(){
 let(mut c,packet,_intent,q,settings,identity)=telegram_question_fixture().await;let key=format!("exec_q:{}",q["id"].as_str().unwrap());assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_answer(90,"Unsupported")).await.unwrap());assert_eq!(browser_pref(&mut c,&key).await,q);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT next_update_id FROM agent_telegram_state WHERE key='primary'").fetch_one(&mut c).await.unwrap(),91);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=90").fetch_one(&mut c).await.unwrap();assert!(reply.contains("answer_must_match_option"));assert_eq!(sqlx::query_scalar::<_,i32>("SELECT revision FROM application_packets WHERE id=$1").bind(packet["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap(),1);assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_answer(91,"Day")).await.unwrap());assert_eq!(browser_pref(&mut c,&key).await["state"],"answered");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_question_ack_failure_rolls_back_answer_outbox_and_update_cursor(){
 let(mut c,packet,_intent,_q,settings,identity)=telegram_question_fixture().await;let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_telegram_answer_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'exec_q:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_telegram_answer_drop BEFORE UPDATE ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_telegram_answer_drop()").execute(&mut c).await.unwrap();assert_eq!(telegram_answer_update(&mut c,&settings,&identity,telegram_answer(100,"Day")).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT next_update_id FROM agent_telegram_state WHERE key='primary'").fetch_one(&mut c).await.unwrap(),0);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM rust_telegram_outbox").fetch_one(&mut c).await.unwrap(),0);assert_eq!(sqlx::query_scalar::<_,i32>("SELECT revision FROM application_packets WHERE id=$1").bind(packet["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap(),1);sqlx::raw_sql("DROP TRIGGER fixture_telegram_answer_drop ON owner_preferences;DROP FUNCTION fixture_telegram_answer_drop()").execute(&mut c).await.unwrap();
}
#[derive(Clone)]
struct QuestionTransportGate{sent:Arc<tokio::sync::Mutex<Vec<Value>>>,entered:Arc<tokio::sync::Notify>,release:Arc<tokio::sync::Notify>,invalid_receipt:bool}
async fn question_transport_response(axum::extract::State(state):axum::extract::State<QuestionTransportGate>,request:axum::extract::Request)->axum::Json<Value>{let method=request.uri().path().rsplit('/').next().unwrap().to_owned();let payload:Value=serde_json::from_slice(&axum::body::to_bytes(request.into_body(),65536).await.unwrap()).unwrap();let result=match method.as_str(){"getMe"=>json!({"id":123,"is_bot":true,"username":"fictional_bot"}),"getWebhookInfo"=>json!({"url":""}),"getUpdates"=>json!([]),"sendMessage"=>{state.sent.lock().await.push(payload);state.entered.notify_one();state.release.notified().await;json!({"message_id":if state.invalid_receipt{-1}else{33},"chat":{"id":22,"type":"private"}})},_=>panic!("unexpected question transport method")};axum::Json(json!({"ok":true,"result":result}))}
async fn question_transport_fixture(invalid:bool)->(QuestionTransportGate,String,CancellationToken,tokio::task::JoinHandle<()>){let gate=QuestionTransportGate{sent:Arc::new(tokio::sync::Mutex::new(Vec::new())),entered:Arc::new(tokio::sync::Notify::new()),release:Arc::new(tokio::sync::Notify::new()),invalid_receipt:invalid};let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let stop=CancellationToken::new();let shutdown=stop.clone();let router=axum::Router::new().fallback(question_transport_response).with_state(gate.clone());let server=tokio::spawn(async move{axum::serve(listener,router).with_graceful_shutdown(shutdown.cancelled_owned()).await.unwrap();});(gate,format!("http://{address}"),stop,server)}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_prompt_commits_unknown_before_loopback_send_releases_owner_lock_then_saves_force_reply_receipt(){
 let(mut c,packet,intent)=owner_question_packet().await;let(_settings,_identity)=telegram_question_binding(&mut c).await;let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let(gate,endpoint,transport_stop,transport_server)=question_transport_fixture(false).await;let mut values=queue_runtime_values();values.extend(telegram_values(&endpoint));let config=Arc::new(Configuration::from_values(&values).unwrap());let relay=telegram::prepare(&config).await.unwrap().unwrap();let stop=CancellationToken::new();let shutdown=stop.clone();let relay_config=config.clone();let running=tokio::spawn(async move{relay.run(&relay_config,Wake::default(),shutdown).await});tokio::time::timeout(Duration::from_secs(5),gate.entered.notified()).await.unwrap();let key=format!("exec_q:{}",q["id"].as_str().unwrap());let uncertain=browser_pref(&mut c,&key).await;assert_eq!(uncertain["state"],"delivery_unknown");assert!(uncertain["delivery_attempt"].as_str().is_some());assert_eq!(uncertain["message_ids"],json!([]));let mut tx=c.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE NOWAIT").execute(&mut *tx).await.unwrap();tx.commit().await.unwrap();let sent=gate.sent.lock().await;assert_eq!(sent.len(),1);assert_eq!(sent[0]["reply_markup"],json!({"force_reply":true,"selective":true}));assert_eq!(sent[0]["chat_id"],22);drop(sent);gate.release.notify_one();let mut current=Value::Null;for _ in 0..200{current=browser_pref(&mut c,&key).await;if current["state"]=="sent"{break;}tokio::time::sleep(Duration::from_millis(10)).await;}assert_eq!(current["message_ids"],json!([33]));assert_eq!(current["state"],"sent");stop.cancel();assert!(running.await.unwrap().is_ok());transport_stop.cancel();transport_server.await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_prompt_invalid_or_lost_receipt_stays_unknown_and_restart_never_resends(){
 let(mut c,packet,intent)=owner_question_packet().await;telegram_question_binding(&mut c).await;let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let(gate,endpoint,transport_stop,transport_server)=question_transport_fixture(true).await;let mut values=queue_runtime_values();values.extend(telegram_values(&endpoint));let config=Arc::new(Configuration::from_values(&values).unwrap());let relay=telegram::prepare(&config).await.unwrap().unwrap();let relay_config=config.clone();let running=tokio::spawn(async move{relay.run(&relay_config,Wake::default(),CancellationToken::new()).await});tokio::time::timeout(Duration::from_secs(5),gate.entered.notified()).await.unwrap();gate.release.notify_one();assert_eq!(running.await.unwrap().unwrap_err(),Failure("telegram_send_receipt_invalid"));let key=format!("exec_q:{}",q["id"].as_str().unwrap());let before=browser_pref(&mut c,&key).await;assert_eq!(before["state"],"delivery_unknown");let restarted=telegram::prepare(&config).await.unwrap().unwrap();let stop=CancellationToken::new();let shutdown=stop.clone();let relay_config=config.clone();let running=tokio::spawn(async move{restarted.run(&relay_config,Wake::default(),shutdown).await});tokio::time::sleep(Duration::from_millis(100)).await;stop.cancel();assert!(running.await.unwrap().is_ok());assert_eq!(gate.sent.lock().await.len(),1);assert_eq!(browser_pref(&mut c,&key).await,before);transport_stop.cancel();transport_server.await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_packet_notice_binds_only_new_typed_delivery_to_current_owner_outbox(){
 let(mut c,_job,packet)=packet_review_fixture().await;let(settings,_identity)=telegram_question_binding(&mut c).await;bind_review_execution(&mut c,&packet).await;let mut packets=packet_settings();packets.telegram_notices=true;let approved=review_packet(&mut c,packet["id"].as_str().unwrap().parse().unwrap(),review_request(&packet,1,true),&packets).await.unwrap();assert_eq!(approved["approved_revision"],2);let rows:Vec<(String,i64,String)>=sqlx::query_as("SELECT binding,update_id,state FROM rust_telegram_outbox").fetch_all(&mut c).await.unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].0,settings.binding());assert!(rows[0].1<0);assert_eq!(rows[0].2,"pending");assert_eq!(sqlx::query_scalar::<_,String>("SELECT state FROM agent_telegram_deliveries WHERE update_id=$1").bind(rows[0].1).fetch_one(&mut c).await.unwrap(),"pending");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_packet_notice_never_imports_historical_unbound_or_uncertain_delivery(){
 let(mut c,_job,packet)=packet_review_fixture().await;telegram_question_binding(&mut c).await;let key=bind_review_execution(&mut c,&packet).await;let execution=browser_pref(&mut c,&key).await;let mut future=packet.clone();future["revision"]=json!(2);future["approved_revision"]=json!(2);future["lifecycle_state"]=json!("approved_for_manual_handoff");future["readiness"]["state"]=json!("ready_for_manual_handoff");let notice=automated_apply_agents::packet_notice::propose(&future,Some(&execution),&json!({"revision":3,"state":"RUNNING","policy":{"telegram_questions":true}}),None,&automated_apply_agents::notification_preferences::normalize(json!({})).unwrap(),true,chrono::Utc::now()).unwrap().unwrap();let update=notice.telegram.unwrap()["update_id"].as_i64().unwrap();sqlx::query("INSERT INTO agent_telegram_deliveries(update_id,state,reply) VALUES($1,'sending','Retained uncertain old delivery')").bind(update).execute(&mut c).await.unwrap();let mut packets=packet_settings();packets.telegram_notices=true;review_packet(&mut c,packet["id"].as_str().unwrap().parse().unwrap(),review_request(&packet,1,true),&packets).await.unwrap();assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM rust_telegram_outbox").fetch_one(&mut c).await.unwrap(),0);let old:(String,String)=sqlx::query_as("SELECT state,reply FROM agent_telegram_deliveries WHERE update_id=$1").bind(update).fetch_one(&mut c).await.unwrap();assert_eq!(old,("sending".into(),"Retained uncertain old delivery".into()));
}
